 static UUID id(String key){return UUID.nameUUIDFromBytes(("build-payments-052-"+key).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 static final UUID T=id("town"),M=id("mayor");
 Path proof;String phase;int checks,withdrawals,deposits;World world;Location origin;Town town;JavaPlugin owner;DataStore data;BuildPayments payments;ConstructionService construction;ConstructionRefunds refunds;TreasuryService treasury;Player mayor;UUID virtual,insurance,physical,pending;long expectedBalance;final Map<UUID,Double> balances=new HashMap<>();
 interface Work{void run()throws Exception;}
