 void check(boolean value,String label)throws Exception{if(!value)throw new AssertionError(label);checks++;Files.writeString(proof.resolve(phase+"-checks.txt"),"PASS "+label+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);getLogger().info("CHECK "+label);}
 void fail(Throwable error){getLogger().log(java.util.logging.Level.SEVERE,"BUILD PAYMENTS PROBE FAILED",error);try{Files.writeString(proof.resolve("failed.txt"),error.toString());}catch(Exception ignored){}Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
 void later(long ticks,Work action){Bukkit.getRegionScheduler().runDelayed(this,origin,t->{if(!SuiteState.tryRun("Build payment native",()->{try{action.run();}catch(Throwable error){fail(error);}}))later(1,action);},ticks);}
 void until(BooleanSupplier test,Work next,int left)throws Exception{if(test.getAsBoolean()){next.run();return;}if(left<=0)throw new AssertionError("Payment condition timed out: "+data.payments());later(1,()->until(test,next,left-1));}
 boolean done(UUID operation){var p=data.payments().get(operation);return data.writable()&&p!=null&&p.phase()==BuildPayment.Phase.COMPLETE&&!p.needsAudit();}
 double balance(){return town.getAccount().getHoldingBalance(true);}long cents(){return Math.round(balance()*100);}
 @Override public void onEnable(){if(!Files.isRegularFile(Path.of("ALLOW_DISPOSABLE_RAID_PROBE"))||!"127.0.0.1".equals(getServer().getIp())){Bukkit.getPluginManager().disablePlugin(this);return;}proof=getDataFolder().toPath();try{Files.createDirectories(proof);phase=Files.exists(proof.resolve("first-passed.txt"))?"restart":"first";if(phase.equals("restart"))SuiteState.freeze("NeverLandTownyBuilds");}catch(Exception e){fail(e);return;}Bukkit.getGlobalRegionScheduler().runDelayed(this,t->{try{world=Bukkit.getWorlds().getFirst();origin=new Location(world,8,140,8);var chunks=new ArrayList<CompletableFuture<?>>();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)chunks.add(world.getChunkAtAsync(x,z));CompletableFuture.allOf(chunks.toArray(CompletableFuture[]::new)).whenComplete((v,e)->{if(e==null)later(2,this::setup);else fail(e);});}catch(Throwable e){fail(e);}},40);}
 void setup()throws Exception{
  for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)world.addPluginChunkTicket(x,z,this);
  owner=(JavaPlugin)Bukkit.getPluginManager().getPlugin("NeverLandTownyBuilds");data=(DataStore)field(owner,"dataStore");payments=(BuildPayments)field(owner,"payments");construction=(ConstructionService)field(owner,"construction");refunds=(ConstructionRefunds)field(owner,"constructionRefunds");construction.stop();treasury=(TreasuryService)Bukkit.getServicesManager().load(TownyTreasuryApi.class);
  check(owner.isEnabled()&&payments!=null&&treasury!=null,"real Builds payment and Treasury providers enabled");
  var writer=field(data,"writer");var worker=(ThreadPoolExecutor)field(writer,"worker");Runtime.getRuntime().addShutdownHook(new Thread(()->{try{Files.writeString(proof.resolve(phase+"-writer-closed.txt"),"terminated="+worker.isTerminated()+"\n");}catch(Exception ignored){}},"build-writer-evidence"));
  if(phase.equals("first")){var u=TownyUniverse.getInstance();u.newTownInternal("BuildPaymentCity",T);town=TownyAPI.getInstance().getTown(T);var r=u.getDataSource().newResident("BuildPaymentMayor",M);r.setTown(town);town.setMayor(r);r.save();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){var claim=new TownBlock(x,z,u.getWorld(world.getName()));u.addTownBlock(claim);claim.setTown(town);if(x==0&&z==0)town.setHomeBlock(claim);claim.save();}town.setSpawn(origin);town.save();data.town(T);data.markDirty();data.saveOrThrow();}else town=TownyAPI.getInstance().getTown(T);
  mayor=(Player)Proxy.newProxyInstance(Player.class.getClassLoader(),new Class<?>[]{Player.class},(p,m,a)->switch(m.getName()){case "getUniqueId"->M;case "getName"->"BuildPaymentMayor";case "hasPermission","isOp","isOnline"->true;case "getWorld"->world;case "getLocation"->origin;case "getGameMode"->GameMode.SURVIVAL;case "hashCode"->M.hashCode();case "equals"->p==a[0];default->null;});bank();sync(300);
 }
 void sync(int left)throws Exception{try{treasury.sync(town);}catch(IllegalStateException busy){if(left<=0)throw busy;later(1,()->sync(left-1));return;}if(phase.equals("first"))storageGuard();else resume();}
 LevelDefinition level(double price,int quantity){return new LevelDefinition(1,price,0,List.of(new ItemStack(Material.STONE,quantity)),Map.of(),List.of());}
 ProjectDefinition project(String key,LevelDefinition level){return new ProjectDefinition(key,ProjectType.BUILDING,"Native accepted "+key,Material.STONE,"",0,List.of(),Map.of(1,level));}
 ResourceFund seed(String key,int amount)throws Exception{var fund=data.town(T).resourceFund(key,1);fund.add(new ItemStack(Material.STONE),amount);data.markDirty();data.saveOrThrow();return fund;}
 void storageGuard()throws Exception{UUID session=UUID.randomUUID();check(data.lockStorage(T,"warehouse",session),"exclusive open warehouse is registered");var before=data.town(T);var rejected=data.commitAsync(()->before.setLevel("forge",1),()->before.setLevel("forge",0));check(rejected.toCompletableFuture().isCompletedExceptionally()&&before.level("forge")==0&&withdrawals==0,"open warehouse prevents a full snapshot from racing a vanilla inventory transfer");data.unlockStorage(T,"warehouse",session);delayedPurchase();}
 @SuppressWarnings("unchecked")void delayedPurchase()throws Exception{
  var level=level(100,4);var fund=seed("forge",5);var old=data.town(T);
  var atomic=Class.forName("ru.neverland.core.AtomicFiles",true,owner.getClass().getClassLoader());var f=atomic.getDeclaredField("writers");f.setAccessible(true);var locks=(Map<Path,ReentrantLock>)f.get(null);Path file=owner.getDataFolder().toPath().resolve("town-data.yml").toAbsolutePath().normalize();var fileLock=locks.get(file);check(fileLock!=null,"native file replacement lock exists after initial save");var held=new CountDownLatch(1);var release=new CountDownLatch(1);var free=new java.util.concurrent.atomic.AtomicBoolean();
  new Thread(()->{fileLock.lock();try{held.countDown();release.await(8,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{fileLock.unlock();}},"build-file-delay-fixture").start();
  until(()->held.getCount()==0,()->{
   virtual=payments.begin(mayor,town,project("forge",level),level,null,fund,"Native virtual upgrade");check(data.busy()&&!data.payments().containsKey(virtual)&&old.level("forge")==0&&fund.count(new ItemStack(Material.STONE))==5&&withdrawals==0,"delayed fsync publishes neither reservation nor upgrade nor bank debit");
   boolean refused=false;try{old.setLevel("market",1);}catch(IllegalStateException expected){refused=true;}check(refused&&data.town(T)==old,"retained town cannot mutate during write but reads remain available");refused=false;try{fund.add(new ItemStack(Material.STONE),1);}catch(IllegalStateException expected){refused=true;}check(refused,"retained resource fund cannot bypass pending snapshot");
   new Thread(()->{for(int tries=0;tries<1000&&!free.get();tries++){free.set(SuiteState.tryRun("Independent delayed write probe",()->{}));if(!free.get())java.util.concurrent.locks.LockSupport.parkNanos(1_000_000);}},"build-suite-free-fixture").start();later(1,()->until(free::get,()->{check(withdrawals==0,"filesystem wait leaves the shared ledger available and does not charge early");release.countDown();until(()->done(virtual),this::virtualPaid,800);},100));
  },100);
 }
 int stored(){return Arrays.stream(data.town(T).storage()).filter(Objects::nonNull).filter(i->i.getType()==Material.STONE).mapToInt(ItemStack::getAmount).sum();}
 void virtualPaid()throws Exception{check(withdrawals==1&&cents()==9990000&&data.town(T).level("forge")==1,"one exact debit precedes acknowledged virtual upgrade");check(data.payments().get(virtual).terms().actor().equals(M)&&treasury.debitStatus(virtual).get("actor").equals(M.toString()),"initiating player remains identical in core and bank receipt");until(()->data.writable()&&stored()==1,()->{check(data.town(T).existingResourceFund("forge")==null&&stored()==1,"paid materials consumed once and surplus returned once");insurance=payments.insure(mayor,town,25);until(()->done(insurance),this::insured,800);},200);}
 void insured()throws Exception{check(withdrawals==2&&data.town(T).insuranceReserve()==25&&cents()==9987500,"insurance reserve grows only after exact treasury debit");physical(false);}
 void physical(boolean admin)throws Exception{var level=level(200,2);var fund=seed("town_hall",2);var site=new ConstructionSite("town_hall",world.getUID(),1,140,1,BlockFace.NORTH,0,1,1,true);var plan=construction.previewPlan("town_hall",1,null);var preparation=new ConstructionPreparation(ConstructionPreparation.Status.READY,T,site,plan,List.of());physical=payments.begin(mayor,town,project("town_hall",level),level,preparation,fund,"Native physical build");until(()->done(physical),()->{
  var saved=data.town(T).constructionSite("town_hall");check(saved!=null&&saved.active()&&!saved.adminPaused()&&data.town(T).constructionReceipts().get("town_hall").state().equals("ACTIVE"),"paid physical blueprint activates only after saved bank acknowledgement");
  long before=cents();int bankBefore=deposits;var expected=data.town(T).constructionReceipts().get("town_hall").cancel(admin?0:refunds.fee(),"fixture");
  refunds.cancel(T,"town_hall",physical,admin,mayor,M.toString());until(()->data.writable()&&data.town(T).constructionSite("town_hall")==null&&data.town(T).constructionReceipts().get("town_hall").state().equals("DONE"),()->{
   check(deposits==bankBefore+1&&cents()==before+expected.refundCents(),admin?"administrator cancellation returns the entire paid amount once":"player cancellation returns the saved amount minus the configured fee once");check(data.town(T).constructionReceipts().get("town_hall").remaining().isEmpty(),"all cancellation materials reach town warehouse before receipt is closed");
   if(!admin)physical(true);else rejectPurchase();
  },800);
 },800);}
 void rejectPurchase()throws Exception{int stock=stored();var level=level(900000,2);var fund=seed("market",2);UUID rejected=payments.begin(mayor,town,project("market",level),level,null,fund,"Native insufficient budget");until(()->data.writable()&&data.payments().get(rejected)!=null&&data.payments().get(rejected).phase()==BuildPayment.Phase.REJECTED&&!data.payments().get(rejected).needsAudit()&&data.town(T).constructionReceipts().get("market").state().equals("DONE"),()->{check(withdrawals==4&&deposits==2&&stored()==stock+2&&data.town(T).level("market")==0,"definitive bank refusal restores all reserved materials without creating money or an upgrade");holdRestart();},800);}
 void holdRestart()throws Exception{check(withdrawals==4&&deposits==2,"both physical purchases and both refunds have exactly one bank effect");var level=level(50,2);var fund=seed("market",2);var services=Bukkit.getServicesManager();services.unregister(TownyTreasuryApi.class,treasury);boolean refused=false;try{payments.begin(mayor,town,project("market",level),level,null,fund,"Unavailable treasury");}catch(IllegalStateException expected){refused=true;}check(refused&&fund.count(new ItemStack(Material.STONE))==2&&withdrawals==4,"unavailable installed Treasury refuses before taking the resource fund or using a direct bank fallback");services.register(TownyTreasuryApi.class,treasury,Bukkit.getPluginManager().getPlugin("NeverLandTownyTreasuryPlus"),ServicePriority.Normal);pending=payments.begin(mayor,town,project("market",level),level,null,fund,"Native pending restart upgrade");SuiteState.freeze(owner.getName());until(()->!data.busy(),()->{check(data.payments().get(pending).phase()==BuildPayment.Phase.PREPARED&&data.town(T).level("market")==0&&withdrawals==4,"paused owner preserves accepted unpaid intent and never publishes upgrade");expectedBalance=cents();Files.writeString(proof.resolve("expected.txt"),pending+"\n"+expectedBalance+"\n");finish();},100);}
 void resume()throws Exception{var rows=Files.readAllLines(proof.resolve("expected.txt"));pending=UUID.fromString(rows.get(0));expectedBalance=Long.parseLong(rows.get(1));check(withdrawals==0&&deposits==0&&cents()==expectedBalance&&data.payments().get(pending).phase()==BuildPayment.Phase.PREPARED&&data.town(T).level("market")==0,"full restart retains unpaid ID and all earlier balances without repeating effects");check(data.town(T).insuranceReserve()==25&&data.town(T).level("forge")==1,"completed upgrade and insurance reserve survive JVM restart");SuiteState.thaw(owner.getName());until(()->done(pending),()->{check(withdrawals==1&&data.town(T).level("market")==1&&cents()==expectedBalance-5000,"restored pending purchase charges and upgrades exactly once");later(40,()->{check(withdrawals==1&&deposits==0,"terminal receipts remain replay-safe through later scheduled ticks");shutdownStorage();});},800);}
 void shutdownStorage()throws Exception{UUID session=UUID.randomUUID();check(data.lockStorage(T,"warehouse",session),"warehouse edit is live before two-phase shutdown");var contents=data.town(T).storage();var closing=ModuleShutdown.prepare(owner).toCompletableFuture();check(!closing.isDone()&&!data.writable(),"shutdown waits for the open inventory before the final file snapshot");later(2,()->{data.closeStorage(T,"warehouse",session,contents);data.unlockStorage(T,"warehouse",session);until(closing::isDone,()->{if(closing.isCompletedExceptionally())throw new AssertionError("Shutdown receipt failed");check(Arrays.equals(contents,data.town(T).storage()),"last exclusive inventory contents survive final acknowledged shutdown snapshot");finish();},100);});}
 void finish()throws Exception{var saved=new Properties();balances.forEach((k,v)->saved.setProperty(k.toString(),v.toString()));try(var out=Files.newOutputStream(proof.resolve("bank.properties"))){saved.store(out,"Explicit deterministic fixture bank");}TownySettings.setProperty("economy.using_economy",false);TownyUniverse.getInstance().getDataSource().saveAll();Files.writeString(proof.resolve(phase+"-passed.txt"),"PASS "+checks+" checks; actual Folia/Towny/Builds/Treasury, delayed native file writer, bank ordering, virtual and physical purchases, insurance, cancellation and JVM restart; explicit offline player, accepted-project and deterministic bank fixtures; no live Vault/client claimed\n");Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
 void bank()throws Exception{if(Files.exists(proof.resolve("bank.properties"))){var p=new Properties();try(var in=Files.newInputStream(proof.resolve("bank.properties"))){p.load(in);}p.forEach((k,v)->balances.put(UUID.fromString(k.toString()),Double.parseDouble(v.toString())));}
  var adapter=(EconomyAdapter)Proxy.newProxyInstance(EconomyAdapter.class.getClassLoader(),new Class<?>[]{EconomyAdapter.class},(p,m,a)->{Account account=a!=null&&a.length>0&&a[0] instanceof Account x?x:null;UUID id=account==null?null:account.getUUID();double old=balances.getOrDefault(id,0.0);return switch(m.getName()){case "name","toString"->"Repair deterministic native bank fixture";case "hasAccount"->true;case "getBalance"->old;case "newAccount","deleteAccount"->null;case "getFormattedBalance"->String.valueOf(a[0]);case "setBalance"->{balances.put(id,(Double)a[1]);yield true;}case "renameAccount"->true;case "add","subtract"->{double n=(Double)a[1];boolean add=m.getName().equals("add");if(!add&&old<n)yield false;balances.put(id,old+(add?n:-n));if(add)deposits++;else withdrawals++;yield true;}default->throw new UnsupportedOperationException(m.getName());};});
  var f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);var unsafe=(sun.misc.Unsafe)f.get(null);EconomyProvider provider=(EconomyProvider)unsafe.allocateInstance(Class.forName("com.palmergames.bukkit.towny.object.economy.provider.ReserveEconomyProvider",false,Towny.class.getClassLoader()));for(var e:Map.of("economy",adapter,"provider",provider).entrySet()){var x=TownyEconomyHandler.class.getDeclaredField(e.getKey());x.setAccessible(true);x.set(null,e.getValue());}TownySettings.setProperty("economy.using_economy",true);if(phase.equals("first"))town.getAccount().deposit(100000,"disposable repair seed");deposits=withdrawals=0;
 }
